import{_ as s,o as n,a as p,b as c}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"L1到BiasTable数据搬运","link":"/api/SIMD-API/c_api/data_move_guide/l1_bias_table_data_move"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/l1_bias_table_data_move.md","filePath":"api/SIMD-API/c_api/data_move_guide/l1_bias_table_data_move.md","outlineHeaders":[{"level":2,"title":"数据类型与随路转换","slug":"数据类型与随路转换","link":"#数据类型与随路转换"},{"level":2,"title":"连续数据搬运","slug":"连续数据搬运","link":"#连续数据搬运"},{"level":2,"title":"高维切分数据搬运","slug":"高维切分数据搬运","link":"#高维切分数据搬运"},{"level":2,"title":"地址、容量与同步","slug":"地址、容量与同步","link":"#地址、容量与同步"}],"lastUpdated":1791622466000}'),l={name:"api/SIMD-API/c_api/data_move_guide/l1_bias_table_data_move.md"};function e(t,a,d,o,i,_){return n(),p("div",null,[...a[0]||(a[0]=[c(`<div><article class="markdown-body"><h1>L1到BiasTable数据搬运</h1><p>BiasTable Buffer保存Mmad使用的bias。NPU架构版本3510通过<a href="../cube_datamove/cube_compute_load/asc_copy_l12bt_arch_3510.html">asc_copy_l12bt</a>把L1中的偏置数据搬入BiasTable，接口运行在PIPE_MTE1，仅在AIC生效，支持连续和高维切分两种模式。</p><h2 id="数据类型与随路转换">数据类型与随路转换<a class="header-anchor" href="#数据类型与随路转换">​</a></h2><p>源数据类型支持<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>和<code>float</code>，写入BiasTable后的处理方式如下：</p><table><thead><tr><th>源类型</th><th>写入方式</th></tr></thead><tbody><tr><td><code>bfloat16_t</code></td><td>自动转换为<code>float</code>。</td></tr><tr><td><code>half</code></td><td><code>conv_control</code>为1时转换为<code>float</code>；为0时每个元素扩展为32 bit，高16 bit为占位数据。</td></tr><tr><td><code>int32_t</code>、<code>float</code></td><td>保持32位数据格式，<code>conv_control</code>需要设为0。</td></tr></tbody></table><h2 id="连续数据搬运">连续数据搬运<a class="header-anchor" href="#连续数据搬运">​</a></h2><p>连续模式通过<code>size</code>指定一段连续bias数据：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12bt</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">size</span><span class="p">)</span>
</code></pre></div><ul><li><code>size</code>单位为字节，需要32字节对齐；未对齐时，实际搬运量向下取整到32字节。</li><li>源类型为<code>float</code>或<code>int32_t</code>时，<code>size / 32</code>需要是偶数，即实际搬运量需要64字节对齐。</li><li>连续模式不传入<code>conv_control</code>。需要控制<code>half</code>转换方式时，应选择高维切分原型，并把数据配置为一个连续数据块。</li></ul><h2 id="高维切分数据搬运">高维切分数据搬运<a class="header-anchor" href="#高维切分数据搬运">​</a></h2><p>高维切分模式通过数据块个数、每块长度以及源、目的块间间隔描述bias排布：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12bt</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">conv_control</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">n_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">len_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">source_gap</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">)</span>
</code></pre></div><ul><li><code>len_burst</code>以32字节为单位，取值范围为[1, 65535]。</li><li><code>source_gap</code>和<code>dst_gap</code>表示前一数据块结束地址到下一数据块起始地址的间隔，单位为32字节。</li><li><code>n_burst</code>为1时，两个间隔可设为0；<code>n_burst</code>为0时不执行搬运。</li><li>源类型为<code>float</code>或<code>int32_t</code>时，<code>len_burst</code>和<code>dst_gap</code>需要是2的倍数。</li><li><code>conv_control</code>仅对<code>half</code>有效，其他数据类型需要设为0。</li></ul><h2 id="地址、容量与同步">地址、容量与同步<a class="header-anchor" href="#地址、容量与同步">​</a></h2><ul><li>L1源地址需要32字节对齐，BiasTable目的地址需要64字节对齐。</li><li>L1容量上限为512KB，BiasTable容量上限为4KB；高维切分场景需要把最后一个数据块之前的所有间隔计入地址跨度。</li><li>L1由其他流水写入时，在<code>asc_copy_l12bt</code>读取前建立到PIPE_MTE1的依赖。</li><li>BiasTable写入完成后，Mmad通过PIPE_M读取bias前建立PIPE_MTE1到PIPE_M的依赖。</li><li>多次搬运写入重叠BiasTable区域时，使用同流水同步保证前一条指令完成后再覆盖。</li></ul></article></div>`,1)])])}const b=s(l,[["render",e]]);export{h as __pageData,b as default};
